def can_chain(dominoes):
    if not dominoes:
        return []

    def backtrack(remaining, chain, end):
        if not remaining:
            # The chain must close: first stone's left end matches last stone's right end.
            return chain if chain[0][0] == end else None
        for i, (a, b) in enumerate(remaining):
            rest = remaining[:i] + remaining[i + 1:]
            if a == end:
                result = backtrack(rest, chain + [(a, b)], b)
                if result:
                    return result
            if b == end:
                result = backtrack(rest, chain + [(b, a)], a)
                if result:
                    return result
        return None

    for i, (a, b) in enumerate(dominoes):
        rest = dominoes[:i] + dominoes[i + 1:]
        for first, end in (((a, b), b), ((b, a), a)):
            result = backtrack(rest, [first], end)
            if result:
                return result
    return None

